#[test]
#[ignore = "uses an existing full source and prepared graph; no downloads or inference"]
fn scratch_cached_native_prepare_probe() {
    let source = std::path::PathBuf::from(std::env::var_os("PAMIN_NATIVE_MODEL_SOURCE").unwrap());
    let cache = std::path::PathBuf::from(std::env::var_os("PAMIN_NATIVE_TEST_CACHE").unwrap());
    let expected =
        std::path::PathBuf::from(std::env::var_os("PAMIN_EXPECT_PREPARED_PATH").unwrap());
    assert!(expected.is_file());
    let start = std::time::Instant::now();
    let path = native::prepare(&source, &cache).unwrap();
    let seconds = start.elapsed().as_secs_f64();
    assert_eq!(path, expected, "different cache content identity");
    use sha2::Digest as _;
    let graph = std::fs::read(&path).unwrap();
    println!(
        "cache_probe seconds={seconds:.9} graph_sha256={:x} source_bytes={} graph_bytes={}",
        sha2::Sha256::digest(&graph),
        std::fs::metadata(source).unwrap().len(),
        graph.len()
    );
}
